type Check={name:string;status:'PASS'|'FAIL'|'INFO';detail?:unknown};
type Trace={id:number;page:string|null;visible:()=>boolean;focused:()=>boolean;last:{visible:boolean;focused:boolean}};
type Artwork={image:string;size:string;position:string;repeat:string;clipPath:string;width:number;height:number};
type FeedbackView={hidden:boolean;result:string;text:string;frameHidden:boolean;frameDisplay:string;art:Artwork|null;retainedArtwork:Artwork|null;source:Artwork|null;pending:boolean;success:boolean;error:boolean;pointerEvents:string;font:number;rect:{x:number;y:number;width:number;height:number;right:number;bottom:number};viewport:{width:number;height:number;scrollWidth:number};motion:string;animation:string;sourceButton:{id:string;disabled:boolean;artStyle:Artwork|null}};

const root=process.cwd();
const evidenceDir=path.join(root,'work/polish-0121/native-feedback-luna');
const runId=new Date().toISOString().replace(/[:.]/g,'-')+'-'+process.pid;
const profileRoot=fs.mkdtempSync('/private/tmp/pixelstreet-0121-feedback-luna-');
const profileFile=path.join(profileRoot,'solo/profile.json');
const reportPath=path.join(evidenceDir,`native-feedback-0121-${runId}.json`);
const progressPath=path.join(evidenceDir,`progress-${runId}.jsonl`);
const checks:Check[]=[];const errors:string[]=[];const screenshots:string[]=[];const traces=new Map<number,Trace>();
const suppression=(globalThis as any).__pixelStreetFeedback0121Suppression??{};
const control=(globalThis as any).__pixelStreetFeedback0121Control;
const productRoots=['package.json','package-lock.json','tsconfig.json','scripts/build.mjs','scripts/generate-art.mjs','apps/desktop','packages/solo-core','packages/protocol','packages/content','assets','dist'] as const;
const exclusions=['dist/tests/**','dist/native-*.cjs'] as const;
let shell:Awaited<ReturnType<typeof startDesktop>>|undefined;let fixture:Profile|undefined;let manifestPath='';let manifest:{files?:number;canonicalInventorySha256?:string;hashes?:Record<string,string>}|undefined;
let status:'RUNNING'|'PASS'|'FAIL'='RUNNING';

function codePointCompare(a:string,b:string):number{const aa=Array.from(a,c=>c.codePointAt(0)!),bb=Array.from(b,c=>c.codePointAt(0)!);for(let i=0;i<Math.min(aa.length,bb.length);i++)if(aa[i]!==bb[i])return aa[i]-bb[i];return aa.length-bb.length;}
function walk(dir:string):string[]{if(!fs.existsSync(dir))return[];return fs.readdirSync(dir,{withFileTypes:true}).flatMap(entry=>{const file=path.join(dir,entry.name);return entry.isDirectory()?walk(file):[path.relative(root,file)];});}
function productFiles():string[]{return [...new Set(productRoots.flatMap(item=>fs.statSync(path.join(root,item)).isDirectory()?walk(path.join(root,item)):[item]))].filter(file=>!/^dist\/(?:tests\/|native-.*\.cjs$)/.test(file)&&fs.existsSync(path.join(root,file))).sort(codePointCompare);}
function productHashes():Record<string,string>{return Object.fromEntries(productFiles().map(file=>[file,createHash('sha256').update(fs.readFileSync(path.join(root,file))).digest('hex')]));}
function canonicalInventorySha256(hashes:Record<string,string>):string{return createHash('sha256').update(Object.entries(hashes).sort(([a],[b])=>codePointCompare(a,b)).map(([file,hash])=>`${hash}  ${file}\n`).join(''),'utf8').digest('hex');}
function productSnapshot():Record<string,string>{return productHashes();}
let productHashesAtStart:Record<string,string>={};
function page(win:BrowserWindowType):string|null{try{return new URL(win.webContents.getURL()).searchParams.get('page');}catch{return null;}}
function snapshots():Array<Record<string,unknown>>{return [...traces.values()].map(trace=>{try{trace.last={visible:trace.visible(),focused:trace.focused()};return{id:trace.id,page:trace.page,...trace.last};}catch(error){return{id:trace.id,page:trace.page,...trace.last,destroyed:true,error:String(error)};}});}
function record(name:string,detail?:unknown,statusValue:'PASS'|'FAIL'|'INFO'='PASS'):void{checks.push({name,status:statusValue,detail});fs.mkdirSync(evidenceDir,{recursive:true,mode:0o700});fs.appendFileSync(progressPath,JSON.stringify({at:new Date().toISOString(),name,status:statusValue,detail})+'\n',{mode:0o600});}
function replace(target:any,key:string,value:unknown):void{const descriptor=Object.getOwnPropertyDescriptor(target,key);if(descriptor&&!descriptor.configurable&&!descriptor.writable)throw Error('cannot replace '+key);Object.defineProperty(target,key,{configurable:true,enumerable:descriptor?.enumerable??true,writable:true,value});}
function track(win:BrowserWindowType):void{if(traces.has(win.id))return;const visible=win.isVisible.bind(win),focused=win.isFocused.bind(win);traces.set(win.id,{id:win.id,page:page(win),visible,focused,last:{visible:visible(),focused:focused()}});win.webContents.on('did-finish-load',()=>{const t=traces.get(win.id);if(t)t.page=page(win);});win.webContents.on('console-message',(event:any)=>{if(event.level==='error')errors.push(String(event.message).slice(0,800));});}
async function until(fn:()=>Promise<boolean>|boolean,label:string,timeout=20_000):Promise<void>{const end=Date.now()+timeout;while(Date.now()<end){if(await fn())return;await new Promise(resolve=>setTimeout(resolve,35));}throw Error('timeout: '+label);}
async function js<T=unknown>(win:BrowserWindowType,source:string):Promise<T>{let timer:ReturnType<typeof setTimeout>|undefined;try{return await Promise.race([win.webContents.executeJavaScript(source) as Promise<T>,new Promise<T>((_resolve,reject)=>{timer=setTimeout(()=>reject(Error('renderer evaluation timeout in window '+win.id)),15_000);})]);}catch(error){throw Error('renderer evaluation failed in window '+win.id+': '+String(error)+'; source='+source.slice(0,420));}finally{if(timer)clearTimeout(timer);}}
function profile():Profile{const p=shell?.game.state.profile;assert.ok(p,'isolated GameWorker profile unavailable: '+shell?.game.state.error);return p;}
function overlay():BrowserWindowType{const win=shell?.overlay;assert.ok(win&&!win.isDestroyed(),'hidden street overlay unavailable');return win;}
function popup():BrowserWindowType{const win=shell?.popupWindow;assert.ok(win&&!win.isDestroyed(),'shop popup unavailable');return win;}
function casual():BrowserWindowType{const win=shell?.arenaWindow;assert.ok(win&&!win.isDestroyed(),'casual camp window unavailable');return win;}
function makeFixture(now:number):Profile{const p=initialProfile(now);p.tick=1000;p.wallAt=now;p.job='keeper';p.coins=35;p.leisure.companions=Object.fromEntries(Object.keys(COMPANIONS).map(id=>[id,5])) as Profile['leisure']['companions'];p.leisure.active='slime';p.leisure.bonds=initialBonds();p.leisure.materials={...p.leisure.materials,ore:200,herb:200,berry:200,mushroom:200,tea:200,biscuit:200,soup:200,pumpkin:200,snowflower:200,pie:200,snowtea:200};p.atelier=initialAtelier();p.camp=initialCamp();p.village=initialVillage();return parseProfile(p);}
function assertLoadedProfile(actual:Profile,expected:Profile):void{assert.deepEqual(actual,advance(expected,actual.wallAt),'GameWorker loaded the exact generated profile advanced only to its launch timestamp');}

async function clickAt(win:BrowserWindowType,selector:string,options:{allowDisabled?:boolean;forceEnabled?:boolean}={}):Promise<Record<string,unknown>>{
	const literal=JSON.stringify(selector);const out=await js<any>(win,`(()=>{const e=document.querySelector(${literal});if(!e)throw Error('missing target '+${literal});if(e.hidden||e.closest('[hidden]'))throw Error('hidden target '+${literal});if(e.disabled&&!${options.forceEnabled?'true':'false'})throw Error('disabled target '+${literal}+' '+(e.dataset.tooltip||''));if(${options.forceEnabled?'true':'false'})e.disabled=false;e.scrollIntoView({block:'center',inline:'nearest',behavior:'instant'});const r=e.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,hit=document.elementFromPoint(x,y);if(!hit||hit.closest('button')!==e)throw Error('center hit mismatch '+${literal}+' at '+JSON.stringify({x,y,rect:{x:r.x,y:r.y,width:r.width,height:r.height},viewport:{width:innerWidth,height:innerHeight},hit:hit?.outerHTML||null}));for(const type of ['pointerdown','pointerup'])hit.dispatchEvent(new PointerEvent(type,{bubbles:true,cancelable:true,view:window,clientX:x,clientY:y,pointerType:'mouse',button:0}));hit.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,view:window,clientX:x,clientY:y,button:0,detail:1}));return{selector:${literal},x,y,tag:hit.tagName,targetClass:typeof hit.className==='string'?hit.className:'',buttonId:e.id||e.dataset.vRef||'',disabledBefore:${options.forceEnabled?'true':'Boolean(e.disabled)'},label:e.getAttribute('aria-label')||e.textContent.trim(),tooltip:e.dataset.tooltip||e.title||'',softwareInput:'PointerEvent/MouseEvent dispatched to actual hidden-renderer elementFromPoint center'};})()`);
 record('software coordinate click '+selector,out);return out;
}
async function clickScenePoint(win:BrowserWindowType,selector:string):Promise<void>{await clickAt(win,selector);}
async function inspectToast(win:BrowserWindowType,selector:string):Promise<FeedbackView>{return js<FeedbackView>(win,`(()=>{const btn=document.querySelector(${JSON.stringify(selector)}),toast=document.querySelector('.ps-action-notice'),frame=toast?.querySelector('.ps-action-notice-picture'),art=toast?.querySelector('.ps-action-notice-art'),text=toast?.querySelector('.ps-action-notice-text');const artSelector='.inner-art,.v-sprite,.b-buddy-art,.a-good-art,.b-rarity-art,.b-path-emblem,.cw-crop,.cw-prop,.ls-item-art';function pic(e,pseudo){if(!e||e.hidden||e.closest('[hidden]'))return null;const s=getComputedStyle(e,pseudo),w=parseFloat(s.width),h=parseFloat(s.height);if(s.display==='none'||s.visibility==='hidden'||!s.backgroundImage.includes('url(')||!(w>0&&h>0))return null;return{image:s.backgroundImage,size:s.backgroundSize,position:s.backgroundPosition,repeat:s.backgroundRepeat,clipPath:s.clipPath,width:w,height:h};}let source=null;if(btn){for(const e of [...btn.querySelectorAll(artSelector),btn]){source=pic(e,e===btn?'::before':null);if(source)break;}}const target=btn?.getBoundingClientRect(),r=toast?.getBoundingClientRect(),ts=text&&getComputedStyle(text),style=toast&&getComputedStyle(toast),astyle=art&&getComputedStyle(art),ap=art&&getComputedStyle(art),frameStyle=frame&&getComputedStyle(frame),retainedArtwork=art&&art.style.backgroundImage?{image:art.style.backgroundImage,size:art.style.backgroundSize,position:art.style.backgroundPosition,repeat:art.style.backgroundRepeat,clipPath:art.style.clipPath,width:parseFloat(art.style.width),height:parseFloat(art.style.height)}:null,frameHidden=!frame||frame.hidden,frameDisplay=frameStyle?.display||'none',artVisible=!!frame&&!frameHidden&&frameDisplay!=='none'&&frameStyle?.visibility!=='hidden';return{hidden:!toast||toast.hidden,result:toast?.dataset.result||'',text:text?.textContent||'',frameHidden,frameDisplay,art:artVisible?retainedArtwork:null,retainedArtwork,source,pending:!!btn?.classList.contains('ps-action-pending'),success:!!btn?.classList.contains('ps-action-success'),error:!!btn?.classList.contains('ps-action-error'),pointerEvents:style?.pointerEvents||'',font:parseFloat(ts?.fontSize||'0'),rect:r?{x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom}:{x:-1,y:-1,width:0,height:0,right:0,bottom:0},viewport:{width:innerWidth,height:innerHeight,scrollWidth:document.documentElement.scrollWidth},motion:document.body.dataset.motion||document.getElementById('casualUi')?.dataset.motion||'',animation:style?.animationName||'none',sourceButton:{id:btn?.id||btn?.dataset.vRef||'',disabled:!!btn?.disabled,artStyle:astyle?{image:ap.backgroundImage,size:ap.backgroundSize,position:ap.backgroundPosition,repeat:ap.backgroundRepeat,clipPath:ap.clipPath,width:parseFloat(ap.width),height:parseFloat(ap.height)}:null}}})()`);}
async function assertNotice(win:BrowserWindowType,selector:string,expected:string,result:'success'|'error',picture:'match'|'none',label:string):Promise<FeedbackView>{
 await until(async()=>{const v=await inspectToast(win,selector);return !v.hidden&&v.result===result&&v.text===expected;},label+' exact acknowledged notice');
 const v=await inspectToast(win,selector);assert.equal(v.text,expected,label+' notice equals authoritative acknowledgement');assert.equal(v.result,result,label+' success/error tone');assert.equal(v.pointerEvents,'none',label+' notice does not intercept pointer');assert.ok(v.font>=16,label+' notice text remains readable at 16px');assert.ok(v.rect.x>=0&&v.rect.y>=0&&v.rect.right<=v.viewport.width+1&&v.rect.bottom<=v.viewport.height+1,label+' notice stays inside viewport: '+JSON.stringify(v));assert.ok(v.viewport.scrollWidth<=v.viewport.width+1,label+' notice does not create page overflow');
 if(picture==='match'){assert.ok(v.source,label+' clicked button had rendered image');assert.equal(v.frameHidden,false,label+' should display captured button image');assert.notEqual(v.frameDisplay,'none',label+' art frame must be rendered');assert.deepEqual(v.art,v.source,label+' notice image matches actual clicked-button artwork');}
 else{assert.equal(v.frameHidden,true,label+' must not synthesize art for a text-only stop button');assert.equal(v.frameDisplay,'none',label+' art frame is not displayed');assert.equal(v.art,null,label+' has no visible unrelated/fake icon');}
 const className=result==='success'?'success':'error';assert.ok(result==='success'?v.success:v.error,label+' source button receives finite '+className+' mark');assert.ok(!v.pending,label+' source no longer pending after acknowledgement');
 record(label+' visible exact IPC acknowledgement',{result,text:v.text,source:v.source,toastArtwork:v.art,frameHidden:v.frameHidden,pointerEvents:v.pointerEvents,font:v.font,rect:v.rect,viewport:v.viewport,sourceButton:v.sourceButton,motion:v.motion,animation:v.animation});record(label+' art and layout audit',{picture,iconMatch:picture==='match'?JSON.stringify(v.art)===JSON.stringify(v.source):null,insideViewport:true,readableFont:v.font});return v;
}
async function waitNoticeHidden(win:BrowserWindowType,label:string,timeout=6_000):Promise<void>{await until(async()=>(await inspectToast(win,'body')).hidden,label+' notice expiry',timeout);const state=await js<any>(win,'(()=>{const t=document.querySelector(".ps-action-notice"),s=window.__psActionFeedbackStats;return{hidden:!t||t.hidden,activeTimers:s?[...s.active.values()].map(x=>x.delay):[],timerSchedules:s?.scheduled||0,intervalSchedules:s?.intervals||0}})()');assert.equal(state.hidden,true,label+' acknowledged notice becomes hidden after finite timer');record(label+' finite notice timer expires',{...state,boundary:'renderer timers observed by software instrumentation'});}
async function installRendererProbe(win:BrowserWindowType,label:string):Promise<any>{const actual=await js<any>(win,'({visibility:document.visibilityState,hidden:document.hidden,hasFocus:document.hasFocus()})');const result=await js<any>(win,`(()=>{if(window.__psActionFeedbackStats)return{already:true,actual:${JSON.stringify(actual)}};const saved=Object.fromEntries(['hidden','visibilityState','hasFocus'].map(k=>[k,Object.getOwnPropertyDescriptor(document,k)||null]));window.__psVisibilitySaved=saved;Object.defineProperty(document,'hidden',{configurable:true,get:()=>false});Object.defineProperty(document,'visibilityState',{configurable:true,get:()=> 'visible'});Object.defineProperty(document,'hasFocus',{configurable:true,value:()=>false});document.dispatchEvent(new Event('visibilitychange'));const stats={active:new Map(),scheduled:0,intervals:0,rafRequested:0,rafActive:new Map()};window.__psActionFeedbackStats=stats;const nativeSet=window.setTimeout.bind(window),nativeClear=window.clearTimeout.bind(window),nativeInterval=window.setInterval.bind(window),nativeClearInterval=window.clearInterval.bind(window),nativeRaf=window.requestAnimationFrame.bind(window),nativeCancelRaf=window.cancelAnimationFrame.bind(window);window.setTimeout=function(fn,delay,...args){let id;const stack=new Error().stack||'';const wrapped=(...callArgs)=>{stats.active.delete(id);if(typeof fn==='function')return fn(...callArgs);};id=nativeSet(wrapped,delay,...args);stats.active.set(id,{delay:Number(delay)||0,stack:stack.slice(0,400)});stats.scheduled++;return id;};window.clearTimeout=function(id){stats.active.delete(id);return nativeClear(id);};window.setInterval=function(fn,delay,...args){stats.intervals++;return nativeInterval(fn,delay,...args);};window.clearInterval=function(id){return nativeClearInterval(id);};window.requestAnimationFrame=function(fn){let id;id=nativeRaf(t=>{stats.rafActive.delete(id);fn(t);});stats.rafActive.set(id,{stack:(new Error().stack||'').slice(0,300)});stats.rafRequested++;return id;};window.cancelAnimationFrame=function(id){stats.rafActive.delete(id);return nativeCancelRaf(id);};return{actual:${JSON.stringify(actual)},softwareVisibleDocument:{visibility:document.visibilityState,hidden:document.hidden,hasFocus:document.hasFocus()},nativeFocusClaim:'Electron window remains hidden and unfocused; document getters are software-only for screenshot inspection'}})()`);record(label+' software-visible/unfocused renderer observation and timer probe installed',{actual,software:result,native:{visible:win.isVisible(),focused:win.isFocused()},evidence:'temporary document getters and renderer timer wrappers; no native show/focus'});assert.equal(win.isVisible(),false);assert.equal(win.isFocused(),false);return result;}
async function restoreDocumentVisibility(win:BrowserWindowType,label:string):Promise<any>{const result=await js<any>(win,'(()=>{for(const [k,d] of Object.entries(window.__psVisibilitySaved||{})){if(d)Object.defineProperty(document,k,d);else delete document[k]}document.dispatchEvent(new Event("visibilitychange"));return{visibility:document.visibilityState,hidden:document.hidden,hasFocus:document.hasFocus()}})()');record(label+' original document visibility/focus descriptors restored',{result,native:{visible:win.isVisible(),focused:win.isFocused()}});return result;}
async function timerSnapshot(win:BrowserWindowType,label:string,expectIdle:boolean):Promise<any>{const result=await js<any>(win,'(()=>{const s=window.__psActionFeedbackStats;return{active:s?[...s.active.entries()].map(([id,v])=>({id,delay:v.delay,stack:v.stack})):[],scheduled:s?.scheduled||0,intervals:s?.intervals||0,rafRequested:s?.rafRequested||0,rafActive:s?[...s.rafActive.keys()]:[]}})()');if(expectIdle){assert.equal(result.active.length,0,label+' finite toast timer has settled: '+JSON.stringify(result.active));assert.equal(result.intervals,0,label+' no interval loop was created');}record(label+' finite renderer timer/no interval observation',{...result,expectIdle});return result;}
async function tab(win:BrowserWindowType,id:string,panel:string):Promise<void>{await clickAt(win,'#'+id);await until(()=>js<boolean>(win,`!document.getElementById(${JSON.stringify(panel)}).hidden&&document.getElementById(${JSON.stringify(id)}).getAttribute('aria-selected')==="true"`),id+' selected');}
async function setViewport(win:BrowserWindowType,width:number,height=650):Promise<void>{const d=win.webContents.debugger;if(!d.isAttached())d.attach('1.3');await d.sendCommand('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await until(()=>js<boolean>(win,`innerWidth===${width}&&innerHeight===${height}`),'CDP renderer viewport '+width+'x'+height);record('hidden Electron renderer CSS viewport emulated',{width,height,native:{visible:win.isVisible(),focused:win.isFocused()},method:'CDP Emulation.setDeviceMetricsOverride; not visible-screen evidence'});}
