 const street=overlay();await until(()=>js<boolean>(street,'!!document.getElementById("dungeonSign")'),'street dungeon portal ready');await clickAt(street,'#dungeonSign');await until(()=>!!shell?.arenaWindow&&!shell.arenaWindow.isDestroyed(),'hidden casual window created');const win=casual();await until(()=>js<boolean>(win,'document.body.dataset.casualReady==="true"&&!!document.getElementById("campScene")'),'casual camp renderer ready');assert.equal(win.isVisible(),false);assert.equal(win.isFocused(),false);track(win);record('real single-player camp window loaded hidden and unfocused',{page:page(win),native:{visible:win.isVisible(),focused:win.isFocused()}});return win;
