 await setReducedMotion(win,true);const careBefore=profile();await clickAt(win,'[data-v-ref="care-tea"]');await until(()=>profile().sequence===careBefore.sequence+1,'real casual care worker receipt');const cared=profile();assert.equal(cared.village!.life.slime.visits,careBefore.village!.life.slime.visits+1);const careToast=await assertNotice(win,'[data-v-ref="care-tea"]',cared.notice,'success','match','real companion care success');assert.equal(careToast.animation,'none','reduced motion prevents toast animation');await capture(win,'casual-care-toast-1040');await setReducedMotion(win,false);record('actual care interaction returns acknowledged companion response with selected item art',{sequenceBefore:careBefore.sequence,sequenceAfter:cared.sequence,visitsBefore:careBefore.village!.life.slime.visits,visitsAfter:cared.village!.life.slime.visits,notice:cared.notice,toast:careToast});await waitNoticeHidden(win,'care success expiry');

 await openVillageView(win,'csPlans','plans');const navPlans=await inspectToast(win,'[data-v-ref="plan-start"]');assert.equal(navPlans.hidden,true,'plan route alone does not generate toast');await clickAt(win,'[data-v-ref="station-kitchen"]');await clickAt(win,'[data-v-ref="item-tea"]');await clickAt(win,'[data-v-ref="count-10"]');
 const startBefore=profile();await clickAt(win,'[data-v-ref="plan-start"]');await until(()=>profile().sequence===startBefore.sequence+1,'real plan start receipt');const started=profile();assert.equal(started.village!.plans.kitchen?.remaining,10);const startToast=await assertNotice(win,'[data-v-ref="plan-start"]',started.notice,'success','match','real finite plan start');record('real finite plan starts before stop test',{sequenceBefore:startBefore.sequence,sequenceAfter:started.sequence,plan:started.village!.plans.kitchen,notice:started.notice,toast:startToast});
 const stopButton='[data-v-ref="plan-stop"]';await until(()=>js<boolean>(win,`!document.querySelector(${JSON.stringify(stopButton)}).hidden`),'running plan stop button visible');const stopBefore=profile();await clickAt(win,stopButton);await until(()=>profile().sequence===stopBefore.sequence+1,'real casual plan-stop receipt');const stopped=profile();assert.equal(stopped.village!.plans.kitchen,null);assert.equal(stopped.notice,'安排已停止，未完成这一份的材料退回，已完成与已售商品保留。');const stopToast=await assertNotice(win,stopButton,stopped.notice,'success','none','real finite plan-stop success');await capture(win,'casual-plan-stop-toast-1040');record('real plan-stop completion has exact success notice and no invented icon',{sequenceBefore:stopBefore.sequence,sequenceAfter:stopped.sequence,notice:stopped.notice,plan:stopped.village!.plans.kitchen,toast:stopToast});await waitNoticeHidden(win,'plan-stop success expiry');await timerSnapshot(win,'casual feedback timers quiescent after plan-stop expiry',true);

